/** Compute Entrypoint Contract
  *
  * guarantee CASE_08_heat_safe_off_priority
  * @param heat_control_state post-state state variable
  * @param api_regulator_mode incoming data port
  */
pub fn compute_spec_CASE_08_heat_safe_off_priority_guarantee(
  heat_control_state: Isolette_Thermostat_Rust::HeatCommand,
  api_regulator_mode: Isolette_Thermostat_Rust::ThermostatMode) -> bool
{
  implies!(
    (api_regulator_mode == Isolette_Thermostat_Rust::ThermostatMode::INIT) |
      (api_regulator_mode == Isolette_Thermostat_Rust::ThermostatMode::FAILED),
    (heat_control_state == Isolette_Thermostat_Rust::HeatCommand::Off))
}

/** Compute Entrypoint Contract
  *
  * guarantee CASE_09_heat_numeric_partition
  * @param In_heat_control_state pre-state state variable
  * @param heat_control_state post-state state variable
  * @param api_control_basis incoming data port
  * @param api_regulator_mode incoming data port
  */
pub fn compute_spec_CASE_09_heat_numeric_partition_guarantee(
  In_heat_control_state: Isolette_Thermostat_Rust::HeatCommand,
  heat_control_state: Isolette_Thermostat_Rust::HeatCommand,
  api_control_basis: Isolette_Thermostat_Rust::RegulatorControlBasis,
  api_regulator_mode: Isolette_Thermostat_Rust::ThermostatMode) -> bool
{
  (implies!(
    (api_regulator_mode == Isolette_Thermostat_Rust::ThermostatMode::NORMAL) &
      api_control_basis.range_available &
      (api_control_basis.current_value_dF < api_control_basis.lower_dF),
    (heat_control_state == Isolette_Thermostat_Rust::HeatCommand::On))) &
    (implies!(
      (api_regulator_mode == Isolette_Thermostat_Rust::ThermostatMode::NORMAL) &
        api_control_basis.range_available &
        (api_control_basis.current_value_dF > api_control_basis.upper_dF),
      (heat_control_state == Isolette_Thermostat_Rust::HeatCommand::Off))) &
    (implies!(
      (api_regulator_mode == Isolette_Thermostat_Rust::ThermostatMode::NORMAL) &
        api_control_basis.range_available &
        (api_control_basis.current_value_dF >= api_control_basis.lower_dF) &
        (api_control_basis.current_value_dF <= api_control_basis.upper_dF),
      (heat_control_state == In_heat_control_state)))
}

/** Compute Entrypoint Contract
  *
  * guarantee CASE_10_heat_owner_local_output
  * @param heat_control_state post-state state variable
  * @param api_heat_control outgoing data port
  */
pub fn compute_spec_CASE_10_heat_owner_local_output_guarantee(
  heat_control_state: Isolette_Thermostat_Rust::HeatCommand,
  api_heat_control: Isolette_Thermostat_Rust::HeatCommand) -> bool
{
  api_heat_control == heat_control_state
}

/** CEP-T-Guar: Top-level guarantee contracts for manage_heat_source's compute entrypoint
  *
  * @param In_heat_control_state pre-state state variable
  * @param heat_control_state post-state state variable
  * @param api_control_basis incoming data port
  * @param api_regulator_mode incoming data port
  * @param api_heat_control outgoing data port
  */
pub fn compute_CEP_T_Guar(
  In_heat_control_state: Isolette_Thermostat_Rust::HeatCommand,
  heat_control_state: Isolette_Thermostat_Rust::HeatCommand,
  api_control_basis: Isolette_Thermostat_Rust::RegulatorControlBasis,
  api_regulator_mode: Isolette_Thermostat_Rust::ThermostatMode,
  api_heat_control: Isolette_Thermostat_Rust::HeatCommand) -> bool
{
  let r0: bool = compute_spec_CASE_08_heat_safe_off_priority_guarantee(heat_control_state, api_regulator_mode);
  let r1: bool = compute_spec_CASE_09_heat_numeric_partition_guarantee(In_heat_control_state, heat_control_state, api_control_basis, api_regulator_mode);
  let r2: bool = compute_spec_CASE_10_heat_owner_local_output_guarantee(heat_control_state, api_heat_control);

  return r0 && r1 && r2;
}

/** CEP-Post: Compute Entrypoint Post-Condition for manage_heat_source
  *
  * @param In_heat_control_state pre-state state variable
  * @param heat_control_state post-state state variable
  * @param api_control_basis incoming data port
  * @param api_regulator_mode incoming data port
  * @param api_heat_control outgoing data port
  */
pub fn compute_CEP_Post(
  In_heat_control_state: Isolette_Thermostat_Rust::HeatCommand,
  heat_control_state: Isolette_Thermostat_Rust::HeatCommand,
  api_control_basis: Isolette_Thermostat_Rust::RegulatorControlBasis,
  api_regulator_mode: Isolette_Thermostat_Rust::ThermostatMode,
  api_heat_control: Isolette_Thermostat_Rust::HeatCommand) -> bool
{
  // CEP-Guar: guarantee clauses of manage_heat_source's compute entrypoint
  let r0: bool = compute_CEP_T_Guar(In_heat_control_state, heat_control_state, api_control_basis, api_regulator_mode, api_heat_control);

  return r0;
}
